package com.zad.almoslem;
import android.app.Activity;import android.content.Intent;import android.content.res.Configuration;import android.graphics.Color;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import java.util.Locale;
public class LanguageSettingsActivity extends Activity{
String[] names={"العربية","English","Français","اردو","Türkçe"};String[] codes={"ar","en","fr","ur","tr"};int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(8,48,40));getWindow().setNavigationBarColor(Color.rgb(8,48,40));build();}
void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(22),dp(18),dp(24));root.setBackgroundColor(Color.rgb(244,247,243));TextView title=new TextView(this);title.setText("لغة التطبيق");title.setTextSize(23);title.setTextColor(Color.rgb(8,48,40));title.setGravity(Gravity.CENTER);root.addView(title);
TextView desc=new TextView(this);desc.setText("اختر اللغة التي تريد استخدامها في واجهة التطبيق.");desc.setTextSize(14);desc.setTextColor(Color.DKGRAY);desc.setPadding(0,dp(12),0,dp(14));root.addView(desc);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));String saved=getSharedPreferences("zad_settings",MODE_PRIVATE).getString("app_language","ar");int selected=0;for(int i=0;i<codes.length;i++)if(codes[i].equals(saved))selected=i;spinner.setSelection(selected);root.addView(spinner);
Button apply=new Button(this);apply.setText("تطبيق اللغة");root.addView(apply);apply.setOnClickListener(v->{String code=codes[spinner.getSelectedItemPosition()];getSharedPreferences("zad_settings",MODE_PRIVATE).edit().putString("app_language",code).apply();Locale locale=new Locale(code);Locale.setDefault(locale);Configuration config=new Configuration(getResources().getConfiguration());config.setLocale(locale);getResources().updateConfiguration(config,getResources().getDisplayMetrics());Toast.makeText(this,"تم حفظ اللغة. ستظهر الترجمات في التبويبات والقوائم المدعومة، وتستكمل ترجمة بقية الشاشات لاحقًا.",Toast.LENGTH_LONG).show();Intent i=new Intent(this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);finish();});
TextView note=new TextView(this);note.setText("اللغات المتاحة: العربية، الإنجليزية، الفرنسية، الأردية، والتركية. بعض المحتوى الحالي سيظل بالعربية إلى أن تكتمل ترجمته.");note.setTextSize(12);note.setTextColor(Color.GRAY);note.setPadding(0,dp(14),0,0);root.addView(note);setContentView(AppTabs.wrap(this,root,"more"));}
}